//
//  ClaudeIconPack.swift
//  Docky
//
//  The icons Claude offers for a project, redrawn as line SVGs (1.5 pt
//  stroke on a 24 pt grid, in the current color), from Bruno's icon
//  library (~/Documents/Ressources/icones/claude). A pinned app or site can
//  wear one of them, drawn in the theme's colors, in place of its
//  own icon.
//

import AppKit

enum ClaudeIconPack {
    /// The icons' names, in alphabetical order.
    static let names: [String] = svgs.keys.sorted()

    private static var cache: [String: NSImage] = [:]

    /// The icon as a template image, to be tinted where it is drawn.
    static func image(named name: String) -> NSImage? {
        if let cached = cache[name] { return cached }
        // Drawn small in the sidebar, the pack's 1.5 pt line thins out to
        // under a point and gets lost on the colored themes: 2 pt keeps it
        // legible.
        guard let svg = svgs[name]?.replacingOccurrences(of: #"stroke-width="1.5""#, with: #"stroke-width="2""#),
              let image = NSImage(data: Data(svg.utf8)), image.isValid
        else { return nil }
        image.isTemplate = true
        cache[name] = image
        return image
    }

    /// "book-open-text" -> "Book Open Text", for the menus.
    static func title(of name: String) -> String {
        name.split(separator: "-").map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined(separator: " ")
    }

